SELECT current_database();

SELECT table_name
FROM information_schema.tables
WHERE table_schema = 'public';

 -- Q.1: What is the total revenue generated by male vs. female customers?
select
     gender,
     sum(purchase_amount) as revenue
 from customer
 group by gender;

 -- Q.2: which customers used a discount but still spent more than the average purchase amount?
 select
     customer.customer_id,
     customer.purchase_amount
 from customer
 where discount_applied = 'Yes'
 and purchase_amount >=
    (select avg(purchase_amount)
     from customer);

 -- Q.3: which are the top 5 products with the highest average review rating?
 select
     customer.item_purchased,
     round(avg(customer.review_rating::numeric),2) as averge_product_rating
 from customer
 group by item_purchased
 order by avg(review_rating) desc
 limit 5;

 -- Q.4:compare the average purchase amounts between standard and express shipping.
 select
     customer.shipping_type,
     round(avg(customer.purchase_amount),2)
 from customer
 where shipping_type in ('Standard', 'Express')
 group by shipping_type;

 -- Q.5:do subscribed customers spend more?compare average spend and total revenue between subscribers and non-subscribers?
 select
     customer.subscription_status,
     count(customer.customer_id) as total_customer,
     round(avg(customer.purchase_amount),2) as avg_spend,
     round(sum(customer.purchase_amount)) as total_revenue
 from customer
 group by subscription_status
 order by avg_spend, total_revenue desc;

 --Q.6:which 5 products have the highest percentage of purchases with discount applied?
 select
     customer.item_purchased,
     round(100 * sum(
         case when customer.discount_applied = 'Yes'
             then 1
             else 0
     end)/count(*), 2) as discount_rate
 from customer
 group by item_purchased
 order by discount_rate desc
 limit 5;

 --Q.7:segment customers into new, returning and loyal based on their total
 -- number of previous purchases and show the count of each segment.
 with customer_type as (
     select
         customer.customer_id,
         customer.previous_purchases,
         case
             when previous_purchases = 1 then 'New'
             when previous_purchases between 2 and 10 then 'Returning'
             else 'Loyal'
         end as customer_segment
     from customer
 )

 select
     customer_segment,
     count(*) as Numbers_of_customers
 from customer_type
 group by customer_segment;

 --Q.8:what are the top 3 most purchased products within each category?
 with item_counts as (
     select
         customer.category,
         customer.item_purchased,
         count(customer.customer_id) as total_orders,
         row_number() over (partition by customer.category order by count(customer.customer_id) desc) as item_rank
     from customer
     group by category, item_purchased
 )

 select
     item_rank,
     category,
     item_purchased,
     total_orders
 from item_counts
 where item_rank <=3;

--Q.9:are customers who are repeat buyers (more than 5 purchases) also likely to subscribe?
select
    customer.subscription_status,
    count(customer.customer_id) as repeat_buyers
from customer
where previous_purchases>5
group by subscription_status;

--Q.10:what is the revenue contribution of each age group?
select
    customer.age_group,
    sum(customer.purchase_amount) as total_revenue
from customer
group by age_group
order by total_revenue desc;






